contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single test function: send exactly ticketAmount and check relation between pot and contract balance
    function run(uint ticketAmount, uint feeAmount) public payable {
        // ensure this test caller can send the requested value
        require(address(this).balance >= ticketAmount, "insufficient balance");

        // read initial observable values
        uint balBefore = address(c).balance;

        // perform the state-changing call: buy a ticket
        c.play{value: ticketAmount}();

        // observe public variables
        uint potAfter = c.pot();
        uint balAfter = address(c).balance;

        // The distinguishing general rule: if pot was reset to 0 then the contract balance must have decreased by exactly ticketAmount (the pot payout minus fee is taken from contract to player and fee to bank — net the contract's balance drops by ticketAmount)
        // Expressed as: potAfter == 0  =>  balAfter + ticketAmount == balBefore
        assert(!(potAfter == 0) || (balAfter + ticketAmount == balBefore));
    }

    // allow funding this contract for tests
    receive() external payable {}
}

contract InvMutTest {
    C c;
    bool __obsd;
    uint __snap;

    constructor(C _c) { c = _c; }

    // We take the payment amount as a parameter to forward to c.play
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        // restrict to only the ticket amount or else the original contract would revert
        // This makes P's behavior well-defined: c.play requires msg.value == TICKET_AMOUNT
        require(amount == 10);

        // call play and forward Ether; any mid-call observation will be captured by receive()
        c.play{value: amount}();

        // After the external call, __obsd indicates whether we observed the mid-call pot value
        // The assertion: if we observed pot == 0 mid-call then the caller indeed sent the ticket amount
        // (This links the payout event to the correct input; original P only pays when random==0
        //  but mutant pays on the opposite random value, so for some randomness paths the observation
        //  will differ relative to inputs.)
        assert(!__obsd || __snap == 0 ? amount == 10 : true);
    }

    receive() external payable {
        if (!__obsd) {
            __obsd = true;
            // read pot mid-call via the public getter
            __snap = c.pot();
        }
    }
}

