contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive the contract: caller pays exactly ticketAmount in a single play call
    // and then assert that after the call, pot < TICKET_AMOUNT (true for original P, false for mutant M).
    function run(uint ticketAmount, uint feeAmount) public payable {
        // Preconditions: ensure we send exactly the ticket amount and the known constants match
        // We cannot read constants directly, but require the caller provides the correct amount to send.
        require(msg.value == ticketAmount, "must send ticketAmount");
        // Ensure the constants in contract match the provided values so the scenario is meaningful
        require(ticketAmount == C(address(c)).TICKET_AMOUNT(), "ticketAmount mismatch");
        require(feeAmount == C(address(c)).FEE_AMOUNT(), "feeAmount mismatch");

        // Record contract balance before playing (should be zero for the distinguishing scenario)
        // We require c's balance to be zero to match the intended starting pot==0
        require(address(c).balance == 0, "c balance must start at 0");

        // Perform the single state-changing call that may lead to a win
        c.play{value: msg.value}();

        // After the play, observe pot via its public getter and assert the distinguishing property
        uint potAfter = c.pot();

        // On the original contract P: when a win occurs, pot is reset to 0, which is < ticketAmount.
        // On the mutant M: pot is set to ticketAmount, so potAfter == ticketAmount and this assertion can fail.
        assert(potAfter < ticketAmount);
    }

    // Allow the test contract to receive ETH for forwarding to c
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint ticketAmount) public payable {
        require(ticketAmount > 0);
        require(address(this).balance >= ticketAmount);
        // send exactly the ticket amount to play
        c.play{value: ticketAmount}();
        // After a winning play the original contract resets pot to 0, which is strictly less than the ticket amount.
        // The mutated contract sets pot to msg.value, which would make pot >= ticketAmount.
        assert(c.pot() < ticketAmount);
    }
    receive() external payable {}
}

